using System;using System.IO;using System.Linq;using System.Threading;using System.ServiceProcess;using System.Security.Principal;using SargasPC;
namespace Sargon.Setup {public static partial class Manager {
 public static PcScanSettings ReadScanSettings(){RequireAdmin();string path=Path.Combine(ProgramRoot,"service-config.json");NoLinkParent(path);if(!File.Exists(path))throw new IOException("Pirmiausia įdiekite paslaugos dalį.");return Data.Read<PcScanSettings>(path,32768);}
 public static string ScanReport(){RequireAdmin();string file=Path.Combine(DataRoot,"Private","service-plan.json");NoLinkParent(file);var p=Data.Read<DirectoryPlanState>(file,8388608);if(p==null||p.Roots==null||p.Gaps==null||p.Pending==null)throw new IOException("Diskų planas neperskaitytas.");var b=new System.Text.StringBuilder();string hbPath=Path.Combine(DataRoot,"Public","status.json");var hb=ServiceHeartbeat.Read(hbPath);b.AppendLine(ServiceHeartbeat.Fresh(hb,DateTime.UtcNow.Ticks)?"PASLAUGA: "+hb.State+"; versija: "+hb.Version+"; signalas: "+new DateTime(hb.At,DateTimeKind.Utc).ToLocalTime():"DĖMESIO: signalas pasenęs; eiga gali būti tik istorinė.");if(hb.State=="PAUSED_BATTERY")b.AppendLine("Pristabdyta dėl baterijos / nežinomo maitinimo. Prijunkite įkroviklį arba nuimkite „Nauji darbai tik prijungus maitinimą“ ir išsaugokite nuostatas. Vien šis pristabdymas nėra viruso požymis.");b.AppendLine("Šaknys: "+string.Join(", ",p.Roots));b.AppendLine("Ciklas: "+p.Id+"; pradėtas: "+new DateTime(p.Started,DateTimeKind.Utc).ToLocalTime());b.AppendLine("Aplankyta aplankų lygių: "+p.Completed+"; liko eilėje: "+p.Pending.Count+"; spragų: "+p.Unverified+"; aplankų su radiniais: "+p.Findings);b.AppendLine(p.Finished>0?"Ciklas baigtas: "+new DateTime(p.Finished,DateTimeKind.Utc).ToLocalTime():"Ciklas neužbaigtas; po perkrovimo tęsiamas iš išsaugotos vietos. Dabartinis aplankas gali būti tikrinamas iš naujo.");b.AppendLine("Išsamūs praleidimai / ribos (iki 256 įrašų; skaičiuojamos vietos, ne tikslus praleistų failų skaičius):");if(p.Unverified>0&&(p.GapDetails==null||p.GapDetails.Count==0))b.AppendLine("Šiame cikle yra ankstesnių spragų be išsamių priežasčių. Tai nėra virusų skaičius. Ankstesnių skaičių neperrašome; pakartoti galima pažymėjus „Pradėti naują ciklą“.");if(p.GapDetails!=null)foreach(var gap in p.GapDetails)b.AppendLine(Data.Clean(gap.Path)+" — "+Data.CleanLog(gap.Reason));if(p.DetailsOmitted>0)b.AppendLine("Papildomų detalių neišsaugota: "+p.DetailsOmitted);b.AppendLine("Spragų aplankai (iki 1024):");foreach(string gap in p.Gaps)b.AppendLine(Data.Clean(gap));b.AppendLine("\r\nPaskutinio aplanko ClamAV ataskaita (ne viso ciklo rezultatas):");string last=Path.Combine(DataRoot,"Private","last-scan.txt");if(File.Exists(last)){FolderMonitor.NoLinks(last);using(var input=File.OpenRead(last))b.AppendLine(Data.CleanLog(System.Text.Encoding.UTF8.GetString(Data.Bounded(input,65536,null))));}b.AppendLine("Nėra failų blokavimo prieš vykdymą; neprieinami, per dideli, šifruoti failai ar apimties ribos nėra saugūs failai. Radinius tikrinkite paslaugos radinių lange.");return b.ToString();}
 public static void ConfigureScan(PcScanSettings next,Action<string> progress,bool restart=false){RequireAdmin();PcScanPolicy.Validate(next);next.Roots=PcScanPolicy.DriveRoots(next.Roots);foreach(string root in next.Roots){var d=new DriveInfo(root);if(!d.IsReady||(d.DriveType!=DriveType.Fixed&&d.DriveType!=DriveType.Removable))throw new IOException("Diskas neparuoštas arba netinkamo tipo: "+root);FolderMonitor.NoLinks(root);}
  using(var mutex=new Mutex(false,"Global\\SARGON.Setup.v1")){bool held=false;try{try{held=mutex.WaitOne(0);}catch(AbandonedMutexException){held=true;}if(!held)throw new IOException("Kitas paslaugos keitimas jau vyksta.");WindowsServiceAccess.InstalledTool("SARGON.Setup.exe",49);var prior=ReadScanSettings();string config=Path.Combine(ProgramRoot,"service-config.json"),plan=Path.Combine(DataRoot,"Private","service-plan.json");string oldConfig=File.ReadAllText(config);bool changed=restart||prior.Roots==null||!prior.Roots.SequenceEqual(next.Roots,StringComparer.OrdinalIgnoreCase);string archived=null;progress("Stabdoma paslauga ties išsaugoma eiga…");Stop();
   try{if(changed&&File.Exists(plan)){FolderMonitor.NoLinks(plan);archived=Path.Combine(DataRoot,"Private","plan-before-scope-change.json");if(File.Exists(archived))FolderMonitor.NoLinks(archived);Data.Atomic(archived,File.ReadAllText(plan));File.Delete(plan);}Data.Atomic(config,Data.Json().Serialize(next));var sid=(SecurityIdentifier)new NTAccount("NT SERVICE",Name).Translate(typeof(SecurityIdentifier));ProtectConfig(config,sid);using(var s=new ServiceController(Name)){s.Start();s.WaitForStatus(ServiceControllerStatus.Running,TimeSpan.FromSeconds(30));}long start=DateTime.UtcNow.Ticks;bool ready=false;for(int i=0;i<120;i++){Thread.Sleep(500);var hb=ServiceHeartbeat.Read(Path.Combine(DataRoot,"Public","status.json"));if(PcScanPolicy.ReadyForScanCommand(hb,next.Roots,start,DateTime.UtcNow.Ticks)){ready=true;break;}}if(!ready)throw new IOException("Naujas paslaugos signalas nepatvirtintas.");using(var s=new ServiceController(Name))s.ExecuteCommand(130);progress("Nuostatos išsaugotos; pradėjimo / tęsimo užklausa perduota. Baterijos ir CPU apribojimai lieka galioti. Baigtį tikrinkite eigos lange.");}
   catch{Stop();Data.Atomic(config,oldConfig);var sid=(SecurityIdentifier)new NTAccount("NT SERVICE",Name).Translate(typeof(SecurityIdentifier));ProtectConfig(config,sid);if(changed){if(archived!=null)Data.Atomic(plan,File.ReadAllText(archived));else if(File.Exists(plan))File.Delete(plan);}using(var s=new ServiceController(Name))s.Start();throw;}
  }finally{if(held)mutex.ReleaseMutex();}}
 }
}}
